function mergeCongruences(a, m, b, n) {
  if (![a, m, b, n].every(v => typeof v === "bigint"))
    throw new TypeError("Use BigInt residues and moduli");
  if (m <= 0n || n <= 0n) throw new RangeError("Moduli must be positive");
  a = normalizedMod(a, m); b = normalizedMod(b, n);
  const { g, s } = extendedGcd(m, n);
  const delta = b - a;
  if (delta % g !== 0n) return null;
  const reducedN = n / g;
  const k = normalizedMod(s * (delta / g), reducedN);
  const modulus = m * reducedN;
  return { residue: normalizedMod(a + m * k, modulus), modulus };
}

function binaryGcd(a, b) {
  if (typeof a !== "bigint" || typeof b !== "bigint")
    throw new TypeError("Use BigInt integers");
  a = a < 0n ? -a : a; b = b < 0n ? -b : b;
  if (a === 0n && b === 0n) throw new RangeError("Exclude gcd(0,0)");
  if (a === 0n) return b;
  if (b === 0n) return a;
  let scale = 1n;
  while ((a & 1n) === 0n && (b & 1n) === 0n) {
    a >>= 1n; b >>= 1n; scale <<= 1n;
  }
  while ((a & 1n) === 0n) a >>= 1n;
  while (b !== 0n) {
    while ((b & 1n) === 0n) b >>= 1n;
    if (a > b) [a, b] = [b, a];
    b -= a;
  }
  return scale * a;
}

function autokey(text, seed, feedback = "plaintext", decrypt = false) {
  if (typeof text !== "string" || !/^[A-Z]*$/.test(text))
    throw new TypeError("Use uppercase A-Z without spaces");
  if (!Number.isInteger(seed) || seed < 0 || seed > 25)
    throw new RangeError("Seed must be an integer from 0 through 25");
  if (!["plaintext", "ciphertext"].includes(feedback) || typeof decrypt !== "boolean")
    throw new TypeError("Invalid feedback or mode");
  let key = seed, result = "";
  for (const ch of text) {
    const input = ch.charCodeAt(0) - 65;
    const plain = decrypt ? (input - key + 26) % 26 : input;
    const cipher = decrypt ? input : (plain + key) % 26;
    result += String.fromCharCode(65 + (decrypt ? plain : cipher));
    key = feedback === "plaintext" ? plain : cipher;
  }
  return result;
}
